import unittest

from hourglass.gaps import find_gaps
from hourglass.models import Span

OPEN_NINE_TO_FIVE = Span(540, 1020)

class FindGapsTests(unittest.TestCase):
    def test_nothing_worked_is_one_gap(self):
        self.assertEqual(
            find_gaps([], OPEN_NINE_TO_FIVE),
            ["gap 09:00-17:00 (480 min)"],
        )

    def test_gap_between_two_spans(self):
        spans = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            find_gaps(spans, OPEN_NINE_TO_FIVE),
            ["gap 12:00-13:00 (60 min)"],
        )

    def test_gaps_at_both_edges(self):
        spans = [Span(600, 900)]
        self.assertEqual(
            find_gaps(spans, OPEN_NINE_TO_FIVE),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 15:00-17:00 (120 min)",
            ],
        )

    def test_fully_covered_has_no_gaps(self):
        spans = [Span(540, 1020)]
        found = find_gaps(spans, OPEN_NINE_TO_FIVE)
        self.assertEqual(found, [])

    def test_touching_and_overlapping_leave_no_gap(self):
        spans = [
            Span(540, 700),
            Span(690, 800),
            Span(800, 1020),
        ]
        found = find_gaps(spans, OPEN_NINE_TO_FIVE)
        self.assertEqual(found, [])

    def test_order_of_spans_does_not_matter(self):
        spans = [Span(780, 1020), Span(540, 720)]
        self.assertEqual(
            find_gaps(spans, OPEN_NINE_TO_FIVE),
            ["gap 12:00-13:00 (60 min)"],
        )

    def test_span_starting_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(500, 600)], OPEN_NINE_TO_FIVE)

    def test_span_ending_after_closing_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(1000, 1100)], OPEN_NINE_TO_FIVE)
